package org.apache.commons.lang3;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.equals(CharSequence, CharSequence)
 */
public class StringUtils_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        String s = "test";
        assertTrue("Should return true for same instance", StringUtils.equals(s, s));
    }

    @Test
    public void testEquals_BothNull() {
        assertTrue("Should return true when both are null", StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_FirstNull() {
        assertFalse("Should return false when first is null", StringUtils.equals(null, "test"));
    }

    @Test
    public void testEquals_SecondNull() {
        assertFalse("Should return false when second is null", StringUtils.equals("test", null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        assertTrue("Should return true for equal strings", StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        assertFalse("Should return false for unequal strings", StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_BothStrings_DifferentLength() {
        assertFalse("Should return false for different lengths", StringUtils.equals("abc", "abcd"));
    }

    @Test
    public void testEquals_MixedTypes_EqualContent() {
        // Using StringBuilder to trigger the CharSequenceUtils.regionMatches branch
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abc");
        assertTrue("Should return true for different CharSequence implementations with same content", 
            StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_NotEqualContent() {
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("def");
        assertFalse("Should return false for different content", StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_DifferentLength() {
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abcd");
        assertFalse("Should return false for different lengths in mixed types", StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_StringBuilder_Equals_StringBuilder() {
        CharSequence cs1 = new StringBuilder("abc");
        CharSequence cs2 = new StringBuilder("abc");
        assertTrue("Should return true for two StringBuilders with same content", StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_EmptyStrings() {
        assertTrue("Should return true for two empty strings", StringUtils.equals("", ""));
        assertTrue("Should return true for two empty StringBuilders", StringUtils.equals("", new StringBuilder("")));
    }
}
